def table(rows, widths, bold_first_col=False):
    data = [[P(c, CB) for c in rows[0]]] + [[P(c, CB if (bold_first_col and j == 0) else C) for j, c in enumerate(r)] for r in rows[1:]]
    t = Table(data, colWidths=widths, repeatRows=1)
    t.setStyle(TableStyle([('GRID', (0,0), (-1,-1), 0.4, colors.HexColor('#888888')),
                           ('BACKGROUND', (0,0), (-1,0), colors.HexColor('#EEEEEE')),
                           ('VALIGN', (0,0), (-1,-1), 'TOP'),
                           ('LEFTPADDING', (0,0), (-1,-1), 3), ('RIGHTPADDING', (0,0), (-1,-1), 3),
                           ('TOPPADDING', (0,0), (-1,-1), 2), ('BOTTOMPADDING', (0,0), (-1,-1), 2)]))
    for i, r in enumerate(rows):
        if i and r[0].startswith(('<b>', '<i>')) and all(c == '' for c in r[1:]):
            shade = '#E2E2E2' if r[0].startswith('<b>') else '#F4F4F4'
            t.setStyle(TableStyle([('SPAN', (0, i), (-1, i)), ('BACKGROUND', (0, i), (-1, i), colors.HexColor(shade))]
                                  + ([('NOSPLIT', (0, i), (-1, i + 1))] if i + 1 < len(rows) else [])))
    return t

