def _pad(rows, when=None):
    out = []
    for r in rows:
        r = list(r)
        if when is not None: r = [when] + r
        out.append(r + [''] * (4 - len(r)))
    return out
def _g(t, n=4): return ['<b>' + t + '</b>'] + [''] * (n - 1)
def _i(t, n=4): return ['<i>' + t + '</i>'] + [''] * (n - 1)
def _sub(rows): return [(['<i>' + r[0][3:-4] + '</i>'] + r[1:]) if (r[0].startswith('<b>') and all(c == '' for c in r[1:])) else r for r in rows]
